import {analyze,bootstrapDelta,median} from './stats.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={ir:'Insulin resistance',sex:'Recorded sex',age:'Age',bmi:'BMI',sspg:'SSPG',race:'Recorded race',study:'Study enrollment'};
let data,evidence=[],analysis,selected,runId=0,searchId=0;
const fmt=(n,d=3)=>Number.isFinite(n)?n.toFixed(d):'—';
const pformat=p=>p<.001?p.toExponential(1):p.toFixed(3);
const qcut=()=>Number($('threshold').value);
function controls(){const f=$('metadata').value,extra=['race','study'].includes(f);$('pairControls').hidden=!extra;if(extra&&data){const counts=new Map();for(const r of data.samples.filter(s=>s.event==='Healthy')){if(!counts.has(r[f]))counts.set(r[f],new Set());counts.get(r[f]).add(r.subject)}const options=[...counts].sort((a,b)=>b[1].size-a[1].size);if($('pairControls').dataset.field!==f){const html=options.map(([v,ids])=>`<option value="${esc(v)}">${esc(v)} (${ids.size} people)</option>`).join('');$('negativeGroup').innerHTML=html;$('positiveGroup').innerHTML=html;$('positiveGroup').selectedIndex=1;$('pairControls').dataset.field=f}$('metadataNote').textContent=f==='race'?'Source codes retained without guessing their definitions. Small categories (<5 people) cannot be tested. Recorded race is not a measure of genetic ancestry.':'Enrollment labels, not exercise exposure or intervention effects.'}$('comparison').innerHTML=extra?'Select two recorded categories below.':f==='ir'?'<strong>Insulin resistant (IR)</strong><br>compared with insulin sensitive (IS)':f==='sex'?'<strong>Recorded M</strong><br>compared with recorded F':`<strong>${esc(labels[f])}</strong><br>Continuous rank association`}

function dirty(){controls();if(analysis)$('runStatus').textContent='Settings changed. Run analysis to update results.'}
async function run(){searchId++;$('liveResults').innerHTML='';const id=++runId;$('run').disabled=true;$('export').disabled=true;$('runStatus').textContent='Calculating 4,999 participant-level permutations…';await new Promise(r=>setTimeout(r,50));try{const pair=['race','study'].includes($('metadata').value)?[$('negativeGroup').value,$('positiveGroup').value]:null;if(pair&&pair[0]===pair[1])throw Error('Choose two different categories.');analysis=analyze(data,$('metadata').value,Number($('prevalence').value),4999,pair);if(id!==runId)return;selected=analysis.results.find(r=>evidence.some(e=>e.genus===r.name))||analysis.results[0];$('runStatus').textContent=`Complete · ${analysis.n} independent participants`;render();$('export').disabled=false;$('exportSettings').disabled=false}catch(e){$('runStatus').textContent=e.message;$('exportSettings').disabled=true;$('cohortFlow').textContent='Analysis not run for these settings. Any results below belong to the previous successful comparison.'}finally{$('run').disabled=false}}
function render(){const a=analysis,hit=a.results.filter(r=>r.q<=qcut()).length;const nSamples=a.people.reduce((s,p)=>s+p.n,0);const p=data.provenance;$('cohortFlow').textContent=`${p.eligibleSamples} eligible samples / ${p.eligibleParticipants} people → ${p.healthySamples} Healthy samples / ${p.healthyParticipants} people → ${nSamples} samples / ${a.n} people with selected metadata/categories. Repeated visits are combined into one median per person; each plotted dot is one person.`;$('metrics').innerHTML=`<div class="metric"><b>${a.n}</b><span>${a.categorical?`${a.n1} ${a.positive} / ${a.n0} ${a.negative}`:'independent participants'}</span></div><div class="metric"><b>${a.results.length}</b><span>features tested · ${nSamples} samples</span></div><div class="metric"><b>${hit}</b><span>q ≤ ${qcut()} · ${esc(labels[a.field])}</span></div>`;$('effectCaption').textContent=a.categorical?`Rank-biserial effect · positive = higher in ${a.positive}`:`Spearman correlation with ${labels[a.field]}`;$('empty').hidden=hit>0;$('empty').textContent='No features pass the selected FDR threshold. The strongest exploratory signals are shown below; they are not established differences.';
 const top=a.results.slice(0,12);$('plot').innerHTML=top.map(r=>`<button class="forest-row ${selected?.name===r.name?'selected':''}" data-index="${r.index}" aria-label="Explore ${esc(r.name)}, effect ${fmt(r.effect)}, q ${pformat(r.q)}"><span class="name">${esc(r.name.replaceAll('_',' '))}</span><span class="track"><i class="${r.q<=qcut()?'hit':''}" style="left:${(r.effect+1)*50}%"></i></span><span class="effect-value">${r.effect>0?'+':''}${fmt(r.effect,2)}</span></button>`).join('')+'<div class="axis"><span>−1</span><span>0</span><span>+1</span></div>'+`<div class="direction"><span>${a.categorical?`Higher in ${a.negative}`:'Negative association'}</span><span>${a.categorical?`Higher in ${a.positive}`:'Positive association'}</span></div>`;
 renderTable();renderTaxon();}
function renderTable(){if(!analysis)return;const needle=$('search').value.toLowerCase(),only=$('significant').checked;const rows=analysis.results.filter(r=>r.name.toLowerCase().includes(needle)&&(!only||r.q<=qcut()));$('results').innerHTML=rows.map(r=>`<tr class="${selected?.name===r.name?'selected':''}"><td><button data-index="${r.index}">${esc(r.name.replaceAll('_',' '))}</button></td><td>${r.effect>0?'+':''}${fmt(r.effect,2)}</td><td class="${r.q<=qcut()?'hit':''}">${pformat(r.q)}</td><td>${Math.round(r.prevalence*100)}%</td></tr>`).join('')||'<tr><td colspan="4">No features match this filter.</td></tr>'}
function select(index){selected=analysis.results.find(r=>r.index===index);searchId++;$('liveResults').innerHTML='';render()}
function renderTaxon(){if(!selected){$('taxonTitle').textContent='No eligible features';$('cards').innerHTML='';return}const a=analysis,r=selected;$('taxonTitle').textContent=r.name.replaceAll('_',' ');$('taxonSubtitle').textContent=`Genus-level feature · ${Math.round(r.prevalence*100)}% participant prevalence`;
 const points=a.people.map(p=>({value:p.values[r.index],group:p.value,id:p.id}));const max=Math.max(...points.map(p=>p.value))*1.08||.01;const w=300,h=165,left=39,right=288,top=17,bottom=130;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Participant median relative abundance distribution for ${esc(r.name)}">`;for(let k=0;k<=3;k++){const y=bottom-(bottom-top)*k/3;svg+=`<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#e2e7de"/><text class="plot-label" x="${left-5}" y="${y+3}" text-anchor="end">${fmt(max*100*k/3,max<.01?2:1)}</text>`}if(a.categorical){[a.negative,a.positive].forEach((g,gi)=>{const ps=points.filter(p=>p.group===g),cx=gi?220:105;ps.forEach((p,i)=>{const x=cx+((i*17%41)-20),y=bottom-p.value/max*(bottom-top);svg+=`<circle cx="${x}" cy="${y}" r="3" fill="${gi?'#166f60':'#a4b7a7'}" opacity=".7"><title>${esc(p.id)}: ${fmt(p.value*100)}%</title></circle>`});const y=bottom-median(ps.map(p=>p.value))/max*(bottom-top);svg+=`<line x1="${cx-26}" x2="${cx+26}" y1="${y}" y2="${y}" stroke="#193a38" stroke-width="2"/><text class="plot-label" x="${cx}" y="150" text-anchor="middle">${g} (n=${ps.length})</text>`})}else{const lo=Math.min(...points.map(p=>p.group)),hi=Math.max(...points.map(p=>p.group));for(const p of points){const x=left+(p.group-lo)/(hi-lo||1)*(right-left),y=bottom-p.value/max*(bottom-top);svg+=`<circle cx="${x}" cy="${y}" r="3" fill="#166f60" opacity=".6"><title>${esc(p.id)}: ${p.group}, ${fmt(p.value*100)}%</title></circle>`}svg+=`<text class="plot-label" x="${left}" y="150">${fmt(lo,1)}</text><text class="plot-label" x="${right}" y="150" text-anchor="end">${fmt(hi,1)}</text><text class="plot-label" x="165" y="163" text-anchor="middle">${esc(labels[a.field])}</text>`}svg+='</svg>';
 let ci='';if(a.categorical){const lo=points.filter(p=>p.group===a.negative).map(p=>p.value),hi=points.filter(p=>p.group===a.positive).map(p=>p.value),interval=bootstrapDelta(hi,lo);ci=`<p class="ci">Median difference (${a.positive} − ${a.negative}): <b>${fmt(r.delta)} pp</b><br>95% bootstrap interval: ${fmt(interval[0])} to ${fmt(interval[1])} pp</p>`}$('distribution').innerHTML='<div class="distribution-title">Participant median relative abundance (%)</div><div class="distribution">'+svg+'</div>'+ci;
 const passes=r.q<=qcut();$('interpretation').innerHTML=`<b>${passes?'Passes the selected FDR threshold':'Exploratory signal · not FDR significant'}</b>${a.categorical?`This feature tends to rank ${r.effect>=0?'higher':'lower'} in ${a.positive} than ${a.negative} participants.`:`The rank association with ${esc(labels[a.field])} is ${r.effect>=0?'positive':'negative'}.`} q = ${pformat(r.q)}. ${passes?'This unadjusted association may reflect other differences between participants.':'This analysis does not provide sufficient evidence of an association at the selected threshold.'} It does not tell us whether this microbe is beneficial or harmful for an individual.`;
 const cards=evidence.filter(e=>e.genus===r.name);$('cards').innerHTML=cards.length?cards.map(e=>`<article class="evidence-card"><div class="kind">${esc(e.studyType)} · ${esc(e.year)}</div><h4>${esc(e.claim)}</h4><p><b>Scope:</b> ${esc(e.scope)}</p><p>${esc(e.population)}</p><p class="caution">${esc(e.limitation)}</p><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)} ↗</a></article>`).join(''):'<div class="notice">No reviewed evidence card is available for this feature yet. This is a coverage gap, not evidence that the microbe has no biological role. Use the literature search below to find candidate studies.</div>';
 if(a.field!=='ir'&&cards.length)$('cards').insertAdjacentHTML('afterbegin','<p class="caution">These initial cards focus on metabolic health. They have not been reviewed specifically for your selected metadata column.</p>');
 $('literatureSearch').disabled=r.name.startsWith('unclassified');if(r.name.startsWith('unclassified'))$('liveResults').textContent='Unclassified features lack a resolved genus for a targeted literature search.';
}
function exportResults(){const a=analysis,fields=['genus','effect','p','q','prevalence','medianPositive','medianNegative','delta'];const quote=s=>'"'+String(s??'').replaceAll('"','""')+'"';const csv=[fields.join(','),...a.results.map(r=>[r.name,...fields.slice(1).map(k=>r[k])].map(quote).join(','))].join('\n');download(csv,'greengenes-results.csv','text/csv')}
function exportSettings(){const a=analysis;download(JSON.stringify({dataSource:data.provenance,field:a.field,categories:a.categorical?{reference:a.negative,comparison:a.positive}:null,method:a.categorical?'permutation Wilcoxon rank-sum':'permutation Spearman',aggregation:'per-participant median of exact-matched Healthy visits',effect:a.categorical?'rank-biserial (positive: '+a.positive+')':'Spearman rho',deltaUnit:'percentage points',multipleTesting:'Benjamini-Hochberg across all tested features',fdrThreshold:qcut(),prevalenceThreshold:a.prevalence,permutations:a.permutations,seed:a.seed,participants:a.people.map(p=>({id:p.id,metadata:p.value,samples:p.n})),covariates:[],retrieved:'2026-10-17'},null,2),'greengenes-analysis-settings.json','application/json')}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),link=document.createElement('a');link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function searchLiterature(){if(!selected)return;const taxon=selected.name,context=$('context').value.trim().replace(/["\\]/g,' '),id=++searchId;const query=`TITLE_ABS:"${taxon.replaceAll('_',' ')}"${context?` AND TITLE_ABS:"${context}"`:''}`;const url='https://www.ebi.ac.uk/europepmc/webservices/rest/search?'+new URLSearchParams({query,format:'json',resultType:'core',pageSize:'5'});$('literatureSearch').disabled=true;$('liveResults').textContent='Searching Europe PMC…';try{const response=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('Search service returned '+response.status);const body=await response.json();if(id!==searchId)return;const papers=body.resultList?.result||[];$('liveResults').innerHTML=`<p class="small">${body.hitCount||0} candidate matches · retrieved ${new Date().toISOString().slice(0,10)}. Relevance and study quality require review.</p>`+papers.map(p=>{const title=esc(p.title),abstract=p.abstractText?new DOMParser().parseFromString(p.abstractText,'text/html').body.textContent:'';const link=p.doi?'https://doi.org/'+encodeURIComponent(p.doi):'https://europepmc.org/article/'+encodeURIComponent(p.source)+'/'+encodeURIComponent(p.id);return`<article class="paper"><a href="${esc(link)}" target="_blank" rel="noopener">${title} ↗</a><small>${esc(p.pubYear)} · ${esc(p.journalInfo?.journal?.title||p.source)}</small>${abstract?`<details><summary>Read source abstract</summary><p>${esc(abstract)}</p></details>`:'<p class="small">No abstract available.</p>'}</article>`}).join('')+(papers.length?'':'<p class="small">Try a broader context, such as diabetes, or leave the context blank.</p>')}catch(e){if(id===searchId)$('liveResults').innerHTML=`<p class="small">Live search unavailable: ${esc(e.message)}.</p><a class="source-link" target="_blank" rel="noopener" href="https://europepmc.org/search?query=${encodeURIComponent(query)}">Open this search in Europe PMC ↗</a>`}finally{if(id===searchId)$('literatureSearch').disabled=false}}
$('negativeGroup').addEventListener('change',dirty);$('positiveGroup').addEventListener('change',dirty);$('metadata').addEventListener('change',dirty);$('prevalence').addEventListener('change',dirty);$('threshold').addEventListener('change',()=>{if(analysis)render()});$('run').addEventListener('click',run);$('search').addEventListener('input',renderTable);$('significant').addEventListener('change',renderTable);$('plot').addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(b)select(Number(b.dataset.index))});$('results').addEventListener('click',e=>{const b=e.target.closest('[data-index]');if(b)select(Number(b.dataset.index))});$('export').addEventListener('click',exportResults);$('exportSettings').addEventListener('click',exportSettings);$('literatureSearch').addEventListener('click',searchLiterature);$('methodsBtn').addEventListener('click',()=>$('methods').showModal());$('closeMethods').addEventListener('click',()=>$('methods').close());controls();
try{const responses=await Promise.all([fetch('data.json'),fetch('literature.json')]);for(const r of responses)if(!r.ok)throw Error('Data could not be loaded');[data,evidence]=await Promise.all(responses.map(r=>r.json()));renderDataset();controls();await run()}catch(e){$('runStatus').textContent=e.message;$('run').disabled=true}

function renderDataset(){const p=data.provenance;$('datasetSummary').innerHTML=`<span class="smallcaps">HMP2Data · Greengenes 13_5</span><div><b>${p.eligibleSamples}</b><span>eligible samples</span><b>${p.eligibleParticipants}</b><span>participants</span><b>${p.namedGenusFeatures}</b><span>genus features¹</span></div><p>From ${p.rawFecalSamples} fecal records · ≥ ${p.minimumRetainedReads.toLocaleString()} retained reads<br>¹ Before participant prevalence and variation filters.<br>Samples are visits; participants are unique people. People can contribute several samples.</p>`;$('datasetMethods').textContent=`HMP2Data T2D16S processed OTU counts, using Greengenes 13_5 taxonomy. Starting data: ${p.rawFecalSamples} fecal records and ${p.otuFeatures.toLocaleString()} OTU features. Exact visit-token and subject joins plus quality filters retain ${p.eligibleSamples} samples from ${p.eligibleParticipants} participants. Exclusions (in order): ${p.exclusions.body_site_filename_conflict||0} body-site/filename conflicts, ${p.exclusions.ambiguous_duplicate_visit} records with duplicate fecal visit IDs, ${p.exclusions.below_1000_retained_reads} records below 1,000 retained OTU reads, ${p.exclusions.no_exact_visit_metadata} records lacking exact visit metadata. The minimum depth is an exploratory QC choice. No replicate records are pooled. Named genus counts are summed across OTUs and divided by ALL retained OTU reads per sample, including OTUs without a genus label. There are ${p.namedGenusFeatures} named genus features before analysis filters. Only Healthy visits are analyzed (${p.healthySamples} samples from ${p.healthyParticipants} participants before selected-metadata exclusions). Each participant contributes their median. Default IR/IS cohort: ${p.defaultIR} IR and ${p.defaultIS} IS participants, from ${p.defaultSamples} samples. This dataset is analyzed independently of the prior Stanford abundance matrix.`;}
